from pycbc.waveform import get_td_waveform
for a in ['SEOBNRv4_opt', 'IMRPhenomD', 'TaylorT4']:
    try:
        hp,_ = get_td_waveform(approximant=a, mass1=30, mass2=30, delta_t=1.0/2048, f_lower=20)
        print(a, 'OK', 'len=', len(hp), 'start_time=', hp.start_time)
    except Exception as e:
        print(a, 'FAIL:', e)
"", "summary": "Test each approximant works"}

